"""Private text prompts to OpenAI's Responses API using only the standard library."""
import json
import os
import ssl
import urllib.request


class OpenAIClient:
    """Send private text prompts to OpenAI's Responses API."""

    DEFAULT_URL = "https://api.openai.com/v1/responses"

    def __init__(self, api_key=None):
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise ValueError("OpenAI API key is required. Set OPENAI_API_KEY or pass api_key.")

    def send(self, prompt, model="gpt-4o-mini", url=None):
        url = url or self.DEFAULT_URL
        payload = {
            "model": model,
            "input": [{"role": "user", "content": [{"type": "input_text", "text": prompt}]}],
        }
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(
            url,
            data=data,
            headers={
                "Content-Type": "application/json",
                "Authorization": f"Bearer {self.api_key}",
            },
            method="POST",
        )
        ctx = ssl.create_default_context()
        with urllib.request.urlopen(req, context=ctx) as resp:
            return json.loads(resp.read().decode("utf-8"))
